INTRO = {
 "t0924a": "《药师如来念诵仪轨》为唐代不空三藏所译，是依药师如来而修念诵供养的密教仪轨。卷首先叙说法缘起与「结愿神咒」（即药师灌顶真言）及持诵功德，次讲受持十万遍后治地筑坛、安药师像与十二神将、日光月光二菩萨，并明根本印、阏伽印、涂香、花、烧香、花座、普供养、发遣等诸印真言；后附转祸延寿、降伏恶人、治种种病、咒水咒食等用法，末以日本古写本的抄校题记收束，可供药师法门课诵修持之用。",
 "t1181": "《大方广菩萨藏经中文殊师利根本一字陀罗尼经》为唐代宝思惟所译，专说文殊师利童子的根本一字咒。全经以世尊于净居天宝庄严道场普告诸天为端，赞此咒为「一切如来秘密心大神咒王」，能消灾障、灭恶梦、除怨敌、净五逆四重十恶之罪、成办善事；并明持咒护境的次第（一遍护一身乃至七遍护四天下）、咒水洗面、咒香熏衣、治齿痛、助产、取箭、求子、治头痛疟病、治鬼病、结咒索除厄等种种用法，末以殷重劝持、勿得轻慢作结。",
 "t1384": "《佛说钵兰那赊嚩哩大陀罗尼经》为宋代法贤所译，是宣说「钵兰那赊嚩哩」大陀罗尼的密教经典。世尊因愍念众生多造罪业、堕于恶趣，纵得人身亦身肢不具、薄福少慧，常为恶魔恶鬼所恼，故为阿难宣说此陀罗尼以辟除恶魔恶鬼；凡至诚受持读诵供养者，则恶魔恶鬼悉皆远离、灾害消除、无诸疾疫、所住安隐。经文主体为长篇陀罗尼六十句，以归敬三宝、无量光佛、观自在菩萨为始，次第展开咒名与威用诸句，阿难闻已发愿忆持宣流，作礼而退。",
}

T0924A = [
 ("译者与缘起",
  "【译者与缘起】大兴善寺三藏沙门、大广智不空奉诏翻译。佛一时在维耶离（毗舍离）乐音树下，与大菩萨三万六千人、比丘八万人共在一处，又有十二神王及其眷属、天龙八部大神王。在这样的大众法会之中宣说此法之后，大众都听闻了，无不欢喜，这就名为「结愿神咒」。【义解】本段是全经的卷首：先标出译者不空三藏，再述说法的时处与听众——佛在维耶离乐音树下，与大菩萨、比丘、十二神王及天龙八部等大众共会；末点出此番所说、令众欢喜者，即名「结愿神咒」，为全篇仪轨的缘起与总目。"),
 ("结愿神咒与功德",
  "【结愿神咒与功德】于是薄伽梵（世尊）说出咒语：「南謨薄伽筏帝鞞殺社窶嚕蔽瑠璃鉢喇婆喝囉闍耶怛他揭多怛姪他唵鞞殺逝鞞殺逝鞞殺社三沒揭帝娑婆訶」。若有受持此真言的人，能拔除身中过去生死的一切重罪，不再经历三途（地狱、饿鬼、畜生），免除远离九横（九种横死），超越众苦，于十方世界随处安乐，自在无碍，法应如此。【义解】本段正式举出全经的核心咒语——即上文所谓「结愿神咒」，亦即药师如来的根本真言（药师灌顶真言）；并说明持诵此咒的功德：能拔过去生死重罪、不经历三途、免离九横、超越众苦，随处安乐自在。咒文照录原文用字，不作改写。"),
 ("受持与筑坛",
  "【受持与筑坛】若善男子、善女人等受持读诵此真言，应日夜精勤，以香汤洗浴、著新净衣，如法持守诸戒；诵满真言十万遍之后，到清净之处如法治理地面，用净土筑令平整，以净牛粪和檀香涂成圆坛，用种种杂宝庄严此坛。于坛的中心安置一尊药师如来像：如来左手令执药器（也叫无价珠），右手令作结三界印，身著袈裟、结跏趺坐，安于莲华台上。【义解】本段说受持真言的前行与坛法：受持者须沐浴净衣、严持禁戒，先诵满十万遍；次择清净处治地筑坛，以净牛粪和檀香涂成圆坛、杂宝庄严；坛心安药师如来像，左手执药器（无价珠）、右手结三界印，披袈裟结跏趺坐于莲台，正是依药师法所设的道场。"),
 ("坛上眷属与念诵期限",
  "【坛上眷属与念诵期限】莲台之下，是十二神将及其八万四千眷属，以上首（为首者）居之。又须在莲台如来威光之中，安住日光、月光二菩萨。如此，坛的四方周围为五色；在近前安置两个阏伽器（净水瓶）、商佉（螺）、瓦器等，随意受用，奉献承事尊像。于像前念诵，或四十九日间，或三七（二十一日）：画像坛的四角安置贤瓶，如此昼夜七日之内，诵咒满百千万遍，所求都随心而获无量的果报。【义解】本段承坛法而说坛上的眷属与念诵期限：莲台下安十二神将及八万四千眷属，威光中安日光、月光二菩萨；坛四方五色，前列阏伽器、商佉、瓦器等供具，随意奉献承事；并明念诵期限——或四十九日、或二十一日，坛角置贤瓶，昼夜七日诵满百千万遍，则所求随心、果报无量。"),
 ("除不至心·根本印与阏伽印",
  "【除不至心·根本印与阏伽印】除非不至诚用心，法应如此。所有的利益说不可尽，其余的功能穷劫也说不完。其次说药师如来的根本印：以左右手头指以下的八指，反叉入于掌中，以两大指来回（运动）。咒曰：「唵戰馱祇哩娑婆訶」。（这名为根本印。）其次说阏伽印。【义解】本段先说功德「除不至心」外无量难尽，随即转入手印：举药师如来根本印的结法——左右头指以下八指反叉入掌、二大指来回，并出其咒；末提次说阏伽印，为下文诸印张本。咒文照录原文。"),
 ("阏伽印至花印",
  "【阏伽印至花印】以二手掌捧器顶戴。真言曰：「南莫三曼多沒馱南羯羯哞三摩三摩娑婆訶」。其次说花座真言印，再说涂香印：二手合掌，二头指、二大指端相合如弹指。真言曰：「南莫三曼多沒馱南巘吐羯羅耶娑婆訶」。其次说花印。【义解】本段续说阏伽、涂香等供养印：阏伽印以二手捧器顶戴而诵真言；涂香印则二手合掌、二头指与二大指端相合如弹指状；中间带出花座真言印，末提花印，次第为下文诸供作引。咒文照录原文用字。"),
 ("花印·烧香印·花座印",
  "【花印·烧香印·花座印】花印：二手合掌，二小指微开末节。真言曰：「南莫三曼多沒馱南沒社華娑婆訶」。其次说烧香印：二手合掌，屈如「山」字形。真言曰：「唵那謨仡羅仡羅曼拏微灑曳尸并寧娑婆訶」。其次说花座印：二手背合，以右腕押左腕。真言曰：「唵社皤羅娑蒲悉什皤羅末吒阿」。【义解】本段续说花印、烧香印、花座印三种供养印：花印二手合掌而二小指微开，烧香印二手合掌屈成山形，花座印则二手背合、右腕押左；各出其供养真言，与前后诸印同属药师仪轨的诸种供养次第。咒文照录原文用字。"),
 ("普供养印与发遣",
  "【普供养印与发遣】其次说普供养印：二手作金刚合掌。真言曰：「南莫三曼多沒馱南唵阿凡賀布灑摩尼娑婆訶」。其次念诵，其次说发遣：以禅智指（拇指与食指）取花投于坛中。真言曰：「南莫三曼多沒馱南阿蘖磋蘖磋娑婆訶」。这些法印与咒，能灭除一切苦恼。【义解】本段续说普供养印与发遣之法：普供养印二手作金刚合掌，发遣则以禅智二指取花投于坛中——此为送圣归位的收束；末总赞此法印与咒能灭一切苦恼，正应药师法拔苦之本怀。咒文照录原文用字。"),
 ("转祸延寿之法",
  "【转祸延寿之法】若有人等罪障众多，以及诸妇女，愿想转祸，可依教法造药师像一躯，书写药师经一卷，造幡、四十九盏灯，作七层形如车轮（的灯轮），安置在像前。以五色作索，用印（指）拄（按）住它。打四十九个结，系在那人身上，又转读药师经四十九卷，所有罪障都得解脱，寿命延长，不遇横苦，即得安稳，鬼神之病也都随即除愈。【义解】本段说转祸延寿的修法：凡罪障众多或欲转祸者，依教造药师像、写药师经、造幡与四十九灯（作七层如车轮），列于像前；以五色索结印、打四十九结系于人身，复转读药师经四十九卷，则罪障解脱、寿命延长、不遇横苦、鬼神之病皆愈。此是药师法中「七层灯轮」与「五色续命索」的用法，正见消灾延寿之效。"),
 ("降伏与治病诸法",
  "【降伏与治病诸法】若想降伏恶人，结印以嗔心诵一百八遍，遥打（向对方打去），一切外道即破灭。若有人患心病，加持青木香涂于心上即除愈。若有人患头病，加持桂皮二十遍，服下即除愈。若有人患肿黄（黄疸肿胀），加持郁金香一百八遍涂之即除愈。若有人想让怨家远去，加持苦练子一百八遍，一咒一烧、投于火中烧，那人即远去。【义解】本段列举药师咒的种种应用：降伏恶人以嗔心诵咒遥打、心病加持青木香涂心、头病加持桂皮二十遍服之、肿黄加持郁金香百八遍涂之、令怨家远去则以苦练子一咒一烧投火。所举皆为以咒加持药香或施用的具体法门，显药师真言治病降魔之用。"),
 ("支节痛·晨饮水·咒饮",
  "【支节痛·晨饮水·咒饮】若患身体支节疼痛，咒汤水一百八遍，洗浴即得除愈。若人每日早朝，以水一掬咒七遍饮下，身上所有的恶报都得以消灭，何况本无灾厄的人；以及三业（身口意）之苦也能除愈，并得寿命长远。若咒（加持）饮食物，一切诸毒都不能为害。【义解】本段续说药师咒的日常用法：支节疼痛以咒水百八遍洗浴即愈；每日清晨以一掬水咒七遍饮下，则恶报消灭、三业之苦亦除、寿命长远；若加持饮食，则一切毒不能为损。所见皆是「咒水、咒食」的治病与护身之用，与上文药香诸法一贯。"),
 ("降怨·好梦·治疟",
  "【降怨·好梦·治疟】若见恶人及有怨家，应当念诵此咒，所有起恶心怨家都当降伏，恶心即灭，转而慈心相向。有恐怖之处，应当摄心念诵。若想睡卧时，当诵此咒一百八遍，即得好梦，善于了知吉凶。若有人患疟病，持此咒的人注视患疟之人，急切诵此咒一千八遍，其病即除愈。【义解】本段再举药师咒的三项功用：念咒则怨家恶心自灭、转以慈心相向，恐怖之处亦宜摄心念诵；睡前诵百八遍得好梦、善知吉凶；遇疟病则持咒者对视病人、朗诵一千八遍而病除。皆属以咒摄心、化物、治病之用，与全篇「拔苦」之旨相合。"),
 ("校写题记（一）",
  "【校写题记（一）】保元三年二月二日酉时书写完毕。恭赐大缘房法印御本，书写完毕，留赠后贤，共期佛慧而已。求法沙门觉成。延宝二甲寅年九月十四日，以高山寺法鼓台的本子在仁和寺书写、校对完毕。野泽末资净严，三十六岁。天明元年辛丑天润五月，以觉远僧正本写之。【义解】本段是日本古写本流传下来的抄写题记：记保元三年（1156）觉成书写、延宝二年（1674）净严于仁和寺以高山寺法鼓台本校写、天明元年（1781）以觉远僧正本再写。此类题记反映该仪轨在日本流传与传抄的经过，非经文正文。"),
 ("校勘题记（二）",
  "【校勘题记（二）】慈忍。享和元年辛酉纪年，求得上述本子训为国字（和文）。此药师念诵轨，元文年间已经雕版付印，然而那缺脱的本子，独缺一纸，因此再加校正以流传付梓。丰山长谷寓居沙门快道识。一校加笔完毕。享和癸亥四月十日，慈顺。【义解】本段续记日本刊本的校勘源流：享和元年（1801）慈忍求得和文本，因当时元文年间的刻本独缺一纸，故再加校正付梓，由快道作识、慈顺加笔。二段题记合观，可见此药师念诵仪轨在日本屡经传抄校刻，亦提示整理时当留意异本差异。"),
]

T1181 = [
 ("译者与缘起",
  "【译者与缘起】大唐北印度迦湿弥罗国三藏宝思惟翻译。如是我闻：一时佛住在净居天宝庄严道场中，与大菩萨及净居诸天众共在一处。那时世尊以大慈大悲，在此会中普告一切诸天众说：「你们好好听文殊师利童子行轮咒法，为了要守护众生的缘故。」【义解】本段是全经的卷首：先标出译者宝思惟，再述说法的时处与听众——佛在净居天宝庄严道场，与大菩萨及净居诸天共会；末举世尊普告诸天，将说文殊师利童子的「行轮咒法」，并点明其用意在于守护众生，为下文开示咒法张本。"),
 ("咒王总标",
  "【咒王总标】「一切如来所有的秘密心大神咒王，我如今当为你们开示显说。若有诵持的人，我授记此人就已经持满一切诸咒、悉皆圆满，一切所作都得成就，再没有超过他的。你们应当知道，此陀罗尼在诸咒中是大神咒王，有大神力。若善男子、善女人能够受持，文殊师利童子菩萨常来拥护，或在醒觉时、或在梦中，为他现示身相及诸善事，能令此人生起大欢喜。」【义解】本段总标此咒的地位与利益：世尊先称其为「一切如来秘密心大神咒王」，谓诵者即同持满一切诸咒、所作皆成；再明其为诸咒之王、具大神力，受持者得文殊师利童子常来拥护，醒梦之中现身示相、令生欢喜。此是全文的总纲，先立咒王之名与拥护之益。"),
 ("咒王摄受力",
  "【咒王摄受力】「诸善男子！这咒王尚且能摄得文殊师利童子菩萨，何况其余菩萨以及世、出世间的贤圣等众。再者，善男子！此咒能消灭一切灾障、一切恶梦、一切怨敌、一切五逆四重十恶的罪业、一切恶邪不祥的咒法，也能成办一切善事，使人具足大精进。」【义解】本段承上文而显咒王的威德：谓此咒连文殊师利童子菩萨都能摄得，何况其余菩萨与世出世贤圣；并列举其能消灾障、恶梦、怨敌、五逆四重十恶罪业及恶邪不祥咒法，又能成办一切善事、令具大精进。由「摄圣」与「消业成善」两面，极言此咒之大神力。"),
 ("咒王殊胜·咒索",
  "【咒王殊胜·咒索】「应当知道，此咒在世、出世种种咒中最为殊胜，是诸佛之心，能令一切所愿都得以满足。若用五色线结咒索、系在颈项上，拥护其身，也能令诸愿都得圆满、没有能超过的。」随即说出咒语：「唵齒𡄦（二合，𡄦字离禁反）」。「诸佛子等！」【义解】本段承前说咒王的殊胜并用咒索之法：此咒是诸佛心，能满一切所愿；以五色线结咒索系颈，可拥护其身、令愿圆满。随即正说咒语「唵齿𡄦」，咒末「（二合，𡄦字离禁反）」为音注，指二字合读、以「离禁反」切「𡄦」字之音，照录原文用字与音注。"),
 ("咒力功德·守护次第",
  "【咒力功德·守护次第】「此咒能消灭一切恶邪魍魉诸鬼，是一切诸佛的吉祥之法，也能成就一切神咒。诵此咒的人，能令众生起大慈心、起大悲心，一切障碍都得消灭，所有诸愿都得满足。未作法时，就能成办如意之事。若发无上大菩提心，诵咒一遍，其力能守护自身。」【义解】本段继说咒的功德与「遍数护境」之次第：此咒能灭魍魉恶鬼、为诸佛吉祥之法、成就一切神咒，诵者能令众生生慈悲心、障碍消灭、诸愿满足；并起首言「发菩提心诵一遍护自身」，为下文一遍护一身、乃至七遍护四天下的次第作引。"),
 ("护境遍数·咒水洗面",
  "【护境遍数·咒水洗面】「若诵两遍，其力能守护同伴。若诵三遍，能守护一宅中人。若诵四遍，能守护一城中人。若诵五遍，能守护一国中人。若诵六遍，能守护一天下人。若诵七遍，能守护四天下人。若于清晨诵一遍，咒水洗面，能令看见的人欢喜。」【义解】本段续说「遍数护境」之数：由两遍护同伴，次第增至三遍护一宅、四遍护一城、五遍护一国、六遍护一天下、七遍护四天下，层层扩大；复明清晨诵一遍、咒水洗面能令人见者欢喜。此与上文「一遍护自身」相接，成层层增护的次第。"),
 ("咒香·治齿·助产·取箭",
  "【咒香·治齿·助产·取箭】「咒香熏衣，也能令看见的人欢喜。若患齿痛，咒（加持）揩齿木，嚼之揩齿，所痛即除。若有女人产难之时，取阿吒卢沙迦根或郎伽利迦根，咒之七遍，以无虫水和摩之，涂在产妇脐中，婴儿即易生。或有男子被箭射中，箭头入于筋骨拔不出来，以十年以上的酥三两咒一百八遍，安于疮中并食之，箭头即出。」【义解】本段列举此咒在生活中的应用：咒香熏衣令人欢喜、咒揩齿木治齿痛、咒药根涂脐助产、咒陈酥治箭伤取镞。所举皆为以咒加持香药而施用的具体法门，见此「一字咒王」除守护之外，亦兼治病、助产、疗伤之用。"),
 ("求子方",
  "【求子方】「若妇人五年乃至二三十年不生育男女，或自己有病、或男子有病，或为鬼魅所著种种病等、或为毒药所中，应当以十年以上的酥五两、孔雀羽一两，放入酥中咒二十一遍，煎之后捣为末，再以石蜜一两、大呵梨勒三颗去核取皮相和，咒之一百八遍。」【义解】本段说求子的和药之法：凡妇人多年不孕，无论因自身之病、男子之病、鬼魅所著或毒药所中，皆以陈酥、孔雀羽入酥中咒二十一遍，煎捣成末，再和石蜜与大诃梨勒皮咒一百八遍。此为下文「空腹服之而于七日中有男女」的制方铺陈。"),
 ("服药求子·治头痛·治疟",
  "【服药求子·治头痛·治疟】「常于清晨空腹全部服下，七日之中即有男女。若患头痛，以乌翅羽咒之七遍，拂痛人的头，病即除愈。若患疟病，或一日、二日乃至七日、或经常发作的，以纯乳煮粥，放入好酥一两，咒之一百八遍，给病人服下，即得除愈。」【义解】本段承上文续说服药与治头痛、治疟三事：求子之药于清晨空腹尽服，七日内即有男女；头痛则以乌翅羽咒七遍拂头而愈；疟病则以纯乳粥加好酥、咒百八遍与病人服而愈。皆属以咒加持药食治病的用法，与全经「守护众生」之旨相承。"),
 ("总说合药·治飞头鬼",
  "【总说合药·治飞头鬼】「诸善男子！扼要地说，若想和合一切汤药及想服用，先须至心诵咒二十一遍，便能速得如愿。再者，善男子！若有一切众生为飞头鬼所执持，以手自摩其面，诵咒一百八遍、作可畏之相，便以左手作本生印——屈大拇指在掌中，用后四指押大拇指上、紧把成拳，即自己努目、默诵此咒而看视病人，所患即除。」【义解】本段先总说合药诵咒的要旨，谓凡和合一切汤药及欲服者，先至心诵二十一遍便能速得如愿；次说治飞头鬼所著之法：自摩其面、诵咒百八遍作可畏相，左手结「本生印」（屈拇指在掌、后四指押拇指急握成拳），努目默诵而病人即愈。本段含总说与别法两层。"),
 ("治鬼病·咒索除厄",
  "【治鬼病·咒索除厄】「若人患一切鬼病，以咒咒右手一百八遍，烧安息香熏之，左手作本生印，右手摩病人头，病即除愈。若有怨敌及诸恶梦、种种怖畏、身心不安，以七色线结咒索，作莲花形、或作轮形、或作金刚杵形，咒之一百八遍，烧安息香熏之，于七日之中系在自身颈项上，一切厄难都消散。」【义解】本段说治鬼病与除厄之法：鬼病则以咒咒右手百八遍、烧安息香熏之，左手结本生印、右手摩病人头而愈；怨敌恶梦、身心不安则以七色线结咒索，作成莲花、轮或金刚杵形，咒百八遍、香熏后系于颈项，七日之中则一切厄难消散。见咒与印、索并用的法门。"),
 ("画像除怖·行险护身",
  "【画像除怖·行险护身】「或以牛黄研为墨，在净纸或帛练上画作所怖者的形像，在其四边写「齿𡄦」字围绕之，或作莲花、或作轮字、或作卍字、螺、鱼、金刚钩、宝瓶等围绕之，咒之七遍，所怖即除。诸善男子！若想经过狮子、虎狼、毒蛇、怨贼等一切险难之处，应当净其身心，不得亲近诸女人、不得吃一切五辛、酒肉、芸薹、胡荽，对众生起大悲想，至心诵咒四十九遍，则诸怨恶自然退散，纵使遇到也无不欢喜。」【义解】本段说画像除怖与行险护身两法：前者以牛黄为墨、画所怖者之形，四边以「齿𡄦」字或莲轮卍字、螺鱼钩瓶围绕，咒七遍即除怖；后者若经狮虎毒蛇怨贼险难之处，须净身心、禁五辛酒肉芸薹胡荽、于众生起大悲想，至心诵咒四十九遍，则怨恶退散、遇者欢喜。咒字与画面皆照原文，不作改易。"),
 ("结劝珍重",
  "【结劝珍重】「诸善男子！此咒纵然一切众生，或于一劫、或于无量劫，乃至连名字都不可得闻，何况得见、专心念诵。假使七宝、象马遍布阎浮提，仍是世间坏灭之法。此陀罗尼咒能令众生现在、当来常获安隐，与诸如来、大菩萨众常为眷属，无论为自身、为他身，所愿都得。因此应当殷勤生起难遭之想，切勿轻慢、起疑惑心。」【义解】本段是全经的结劝：先以「一劫乃至无量劫连名字难得闻」反显咒之难遇，再以七宝象马满阎浮提仍属坏灭之法相衬，明此咒能令众生现世当来常得安隐、与诸佛菩萨常为眷属、所愿皆得；末劝殷勤珍重、勿得轻慢疑惑。以此收束全经，令受持者生珍重心。"),
]

T1384 = [
 ("译者与缘起",
  "【译者与缘起】西天译经三藏、朝散大夫、试光禄卿、明教大师臣法贤奉诏翻译。那时世尊告诉阿难说：「我观察世间无量众生，多造罪业、堕于恶趣，经历无量时劫方才得出离；纵然生而为人，也身体肢节不具；即使得身形完具，又薄福少慧，常被恶魔及恶鬼神于昼夜之中伺得其便，种种恼害，不得安隐。」【义解】本段是全经的卷首：先标译者法贤，再举世尊对阿难的告语。世尊观见众生多造罪业而堕恶趣，纵得人身亦有身肢不具、薄福少慧之别，又常为恶魔恶鬼昼夜伺便、不得安隐；此正是下文为说「钵兰那赊嚩哩大陀罗尼」的缘由，先叙众生之苦以起下文。"),
 ("说咒缘起",
  "【说咒缘起】「我怜愍这些众生，为他们宣说钵兰那赊嚩哩大陀罗尼，以辟除恶魔及恶鬼神。若有众生得闻此陀罗尼，发至诚心受持、读诵、供养、恭敬，则令那些恶魔及恶鬼神全都远离，灾害消除、没有诸疾疫，所住之处安隐快乐。」那时世尊随即说出陀罗尼。【义解】本段接上文而说咒的缘起与利益：世尊因怜愍众生而宣说此陀罗尼以辟除恶魔恶鬼；凡闻而受持、读诵、供养、恭敬者，则恶魔恶鬼悉皆远离、灾害消除、无诸疾疫，所居之处安隐快乐。随即引出下文的长篇陀罗尼正文，「钵兰那赊嚩哩」为咒名之音译。"),
 ("大陀罗尼·归敬三宝",
  "【大陀罗尼·归敬三宝】「那谟（引）啰怛那（二合）怛啰（二合）夜（引）野（一）　那莫阿（引）哩也（二合）阿弥多（引）婆（引）野（二）　怛他（引）誐多（引）野（三）　阿啰曷（二合）帝（引）三藐讫三（二合）没驮（引）」【义解】本段是《钵兰那赊嚩哩大陀罗尼》的开端，先归敬三宝与无量光佛：首句「那谟啰怛那怛啰夜野」为归命三宝，次句「那莫阿哩也阿弥多婆野」为归命圣无量光（阿弥陀佛），第三句「怛他誐多野」为归命如来，第四句起「阿啰曷帝三藐讫三没驮」即「应供、正等觉」。咒字后的「（引）」「（二合）」为音注，标示声调与连读，照录原文。"),
 ("大陀罗尼·归敬菩萨",
  "【大陀罗尼·归敬菩萨】「野（四）　那谟（引）阿（引）哩也（二合引）嚩路吉帝（引）说啰（引）野（五）　冒提萨埵（引）野（六）　摩贺（引）萨埵（引）野（七）　摩贺（引）哥（引）噜尼哥（引）野（八）　那谟（引）摩贺（引）」【义解】本段承前咒续归敬观音与菩萨众：「阿哩也嚩路吉帝说啰野」为归命圣观自在，「冒提萨埵野」「摩贺萨埵野」为归命菩提萨埵、摩诃萨埵，「摩贺哥噜尼哥野」为归命大悲者；末「那谟摩贺」起下段之头。咒字音注照录原文。"),
 ("大陀罗尼·归敬（续）",
  "【大陀罗尼·归敬（续）】「娑他（二合引）摩钵啰（二合引）钵多（二合引）钵多（二合引）野（九）　冒提萨埵（引）野（十）　摩贺（引）萨埵野（十一）　嚩（引）摩泥（去声呼）埵（引）那莫泻（引）弥（十二）　怛网（二合引）那摩泻（引）」【义解】本段续前咒之归敬：以「娑他摩钵啰钵多钵多野」归命善逝之智，「冒提萨埵野」「摩贺萨埵野」重归菩萨、大菩萨；「嚩摩泥埵」以下转入「那莫泻弥」等礼敬之词（「那莫」与「泻弥」连读），归命某某之句。「（去声呼）」为音注，标示此字当以去声读。"),
 ("大陀罗尼·咒名与德用",
  "【大陀罗尼·咒名与德用】「弥嚩（引）摩泥（去声）（十三）　必舍（引）唧钵兰那（二合）舍嚩哩（十四）　钵兰那（二合）舍嚩哩婆誐嚩底（十五）　播（引）舍钵啰输驮（引）哩尼（十六）　夜（引）你哥（引）你左（十七）　讷婆（二合）」【义解】本段咒中出现咒名本身——「必舍唧钵兰那舍嚩哩」，即「钵兰那赊嚩哩」（毘舍脂·钵兰那赊嚩哩）；「钵兰那舍嚩哩婆誐嚩底」以「婆誐嚩底」（世尊）称此咒，「播舍钵啰输驮哩尼」为调伏句。此段标示本咒的尊名，是诵持时的核心称念。咒字音注照录原文。"),
 ("大陀罗尼·威用句",
  "【大陀罗尼·威用句】「夜（引）你踰（二合）咄钵（二合）殿帝（引）（十八）　夜哥（引）唧祢（引）怛踰（引）（十九）　夜（引）哥（引）唧咄摩（二合引）踰（引）（二十）　曳（引）计（引）唧讷钵捺啰（二合）嚩（二十一）」【义解】本段咒以「夜哥唧」「曳计唧」为骨干反复出现，配「咄钵殿帝」「讷钵捺啰嚩」等词，属咒中的威用、钩召语句，其义依密咒体例不作字解。「（二合）」标二字合读，「（引）」标长音，照录原文。"),
 ("大陀罗尼·威用句（续）",
  "【大陀罗尼·威用句（续）】「曳（引）计（引）唧讷播（引）夜（引）娑（引）（二十二）曳（引）计（引）唧捺毘𠆙（切身引）婆夜（引）（二十三）　曳（引）计（引）唧讷波娑哩誐（二合引）（二十四）　乌波娑哩誐（二合）三嚩（无钵切）」【义解】本段续前咒之威用句，仍以「曳计唧」为核心，接「讷播夜娑」「讷波娑哩誐」「乌波娑哩誐」等词；「（切身引）」「（无钵切）」为反切音注，分别标示「𠆙」字当切「切身」之音、「嚩」字当切「无钵」之音，照录原文。"),
 ("大陀罗尼·遍摄句",
  "【大陀罗尼·遍摄句】「驮（引）嚩（引）（二十五）　乌咄钵（二合）殿帝（引）（二十六）　萨哩嚩（二合引）尼多（引）你（二十七）　萨哩嚩（二合引）娑多（二合引）（二十八）　萨哩微（二合引）帝（引）嚩（引）罗多（二十九）」【义解】本段续咒，以「萨哩嚩」（一切）为骨干，接「尼多你」「娑多」「微帝嚩罗多」等词，属咒中的遍摄、消灭语句。音注照录原文，其义不作字解。"),
 ("大陀罗尼（三十至三十四）",
  "【大陀罗尼（三十至三十四）】「伊舞（引）咄钵（二合）殿（三十）帝（引）那半尼多（三十一）　怛捺泥（去声呼）那萨帝（引）那（三十二）　萨爹嚩（引）计（引）那（三十三）　伊毘半尼多（引）提瑟吒（二合引）乃（三十四）　摩贺（引）」【义解】本段承前咒，句序三十至三十四，仍为咒中的威用语句，「怛捺泥」下注「（去声呼）」标其声调，音注照录原文，其义依密咒体例不作字解。"),
 ("大陀罗尼·催伏句",
  "【大陀罗尼·催伏句】「满怛啰（二合）钵柰（引）（三十五）　惹（仁佐切，下同）惹惹惹（三十六）　摩摩萨波哩嚩（引）啰写（三十七）　荦羼酤噜（三十八）　玉钵鼎（二合）波哩播（引）罗曩（三十九）　扇（引）鼎莎悉爹（二合引）」【义解】本段续咒（三十五至三十九句），「惹」字下注「（仁佐切，下同）」示其反切之音及下同，属咒中的催伏、摄受语句；音注照录原文，其义不作字解。"),
 ("大陀罗尼·心咒句",
  "【大陀罗尼·心咒句】「野曩酤噜（四十）　怛𭔞他（引）（四十一）　唵（引）阿蜜哩（二合）帝（引）（四十二）　末说娑当（二合引）倪（引）（四十三）　摩（引）末啰摩（引）末啰（四十四）　设末钵啰（二合）设末（四十五）　乌波设末（四十六）」【义解】本段续咒（四十至四十六句），以「怛𭔞他」（即「怛姪他」，意为「所谓、即说咒曰」）为界，后接「唵」字起「阿蜜哩帝」等心咒句，「设末」反复出现。此段由归敬、威用转入正咒核心，是咒体的转折处；音注照录原文，其义不作字解。"),
 ("大陀罗尼·咒名成就句",
  "【大陀罗尼·咒名成就句】「咄努尾咄努（四十七）　咄隶（引）咄母隶（引）娑嚩（二合引）贺（引）（四十八）　唵（引）钵兰那（二合）舍嚩哩娑嚩（二合引）贺（引）（四十九）　那莫设嚩啰（引）𧹞（引）（五十）　摩贺（引）舍嚩啰（引）」【义解】本段续咒（四十七至五十句），第四十八句以「娑嚩贺」（即「娑婆诃」，成就、圆满之义）作结，第四十九句「唵钵兰那舍嚩哩娑嚩贺」即直呼本咒之名而祝愿成就，是咒中的「咒名成就」句；下接「那莫设嚩啰𧹞」等礼敬之词。音注照录原文。"),
 ("大陀罗尼·咒名成就句（续）",
  "【大陀罗尼·咒名成就句（续）】「𧹞（引）（五十一）　必舍（引）唧钵兰那（二合）舍嚩哩（五十二）必舍（引）唧（五十三）　遏设泥（去声呼）末设泥娑嚩（二合引）贺（引）（五十四）　唵（引）必舍（引）唧娑嚩（二合引）贺（引）（五十五）」【义解】本段续咒（五十一至五十五句），再次直呼咒名「必舍唧钵兰那舍嚩哩」及「必舍唧」，并以「娑嚩贺」作结，属咒中的咒名成就与祝愿句；「（去声呼）」为音注，照录原文。"),
 ("大陀罗尼·咒名成就句（再续）",
  "【大陀罗尼·咒名成就句（再续）】「盎酤哩（引）莽酤哩（引）（五十六）　钵兰那（二合）舍嚩哩娑嚩（二合引）贺（引）（五十七）　那莫舍嚩啰（引）𧹞（引）（五十八）　必舍（引）唧钵兰那（二合）舍嚩哩（五十九）　必舍（引）唧娑嚩（二合引）」【义解】本段续咒（五十六至五十九句），「钵兰那舍嚩哩娑嚩贺」等句再三复出，属咒末对咒名的反复称念与祝愿，可见本咒以「钵兰那赊嚩哩」为核心尊名。音注照录原文。"),
 ("咒末·阿难领受",
  "【咒末·阿难领受】「贺（引）（六十）」。那时阿难得闻世尊说此陀罗尼之后，白佛言：「世尊！愿勿有虑。我当忆持、宣流于世，使诸众生获得大善利。」说完这话，即以头顶礼世尊之足，欢喜而退。【义解】本段以咒文第六十句「贺」收束全咒，随即叙阿难领受：阿难闻咒已毕，白佛请勿忧虑，自许当忆持、宣扬流布此咒，令众获大善利，作礼欢喜而退。此是全经的结尾，显阿难承佛付嘱、流通此陀罗尼之愿。"),
]
